{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-djQKQS/src/parse.js","content":"/**
 * Parses the build-graph text format into a graph the scheduler can work
 * with: a map of task name to cost, and a map of task name to the set of
 * names it directly depends on.
 */

import { CliError } from './errors.js'

const NAME_PATTERN = /^[A-Za-z0-9_.-]+$/
const COST_PATTERN = /^[0-9]+$/

function isValidName(name) {
  return NAME_PATTERN.test(name)
}

/**
 * @param {string} text the raw standard input
 * @returns {{ tasks: Map<string, number>, deps: Map<string, Set<string>> }}
 */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const deps = new Map()
  const referencedInOrder = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`error: line ${lineNumber}: expected task <name> <cost>`)
      }
      const [, name, costText] = words
      if (!isValidName(name)) {
        throw new CliError(`error: line ${lineNumber}: invalid task name ${name}`)
      }
      if (!COST_PATTERN.test(costText)) {
        throw new CliError(`error: line ${lineNumber}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(`error: line ${lineNumber}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(costText, 10))
      if (!deps.has(name)) deps.set(name, new Set())
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`error: line ${lineNumber}: expected dep <name> <dependency>...`)
      }
      const [, name, ...dependencyNames] = words
      for (const candidate of [name, ...dependencyNames]) {
        if (!isValidName(candidate)) {
          throw new CliError(`error: line ${lineNumber}: invalid task name ${candidate}`)
        }
      }
      if (!deps.has(name)) deps.set(name, new Set())
      const set = deps.get(name)
      for (const dependencyName of dependencyNames) set.add(dependencyName)
      referencedInOrder.push(name, ...dependencyNames)
    } else {
      throw new CliError(`error: line ${lineNumber}: unknown directive ${directive}`)
    }
  }

  for (const name of referencedInOrder) {
    if (!tasks.has(name)) {
      throw new CliError(`error: unknown task ${name}`)
    }
  }

  return { tasks, deps }
}
"}

