{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-djQKQS/src/schedule.js","content":"/**
 * Turns a parsed build graph into the schedules the CLI reports: the
 * unlimited-worker waves and timings, and the worker-packed simulation.
 * `checkForCycle` must run first; every other function assumes the graph
 * is acyclic.
 */

import { CycleError } from './errors.js'

/**
 * Depth-first search from every task in ascending name order, walking each
 * task's dependencies in ascending name order, looking for a cycle. Throws
 * `CycleError` with the first one found, described from the re-entered task
 * through the search stack back to it.
 */
export function checkForCycle(tasks, deps) {
  const UNVISITED = 0
  const VISITING = 1
  const DONE = 2
  const state = new Map()
  const stack = []

  function visit(name) {
    state.set(name, VISITING)
    stack.push(name)
    const dependencyNames = [...(deps.get(name) ?? [])].sort()
    for (const dependencyName of dependencyNames) {
      const dependencyState = state.get(dependencyName)
      if (dependencyState === VISITING) {
        const startIndex = stack.indexOf(dependencyName)
        throw new CycleError([...stack.slice(startIndex), dependencyName])
      }
      if (dependencyState !== DONE) visit(dependencyName)
    }
    stack.pop()
    state.set(name, DONE)
  }

  for (const name of [...tasks.keys()].sort()) {
    if (state.get(name) !== DONE) visit(name)
  }
}

/**
 * Computes, for every task, its start time, finish time and wave depth
 * under an unlimited number of workers.
 */
export function computeTimings(tasks, deps) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function compute(name) {
    if (finish.has(name)) return
    const dependencyNames = deps.get(name) ?? new Set()
    let taskStart = 0
    let taskDepth = 0
    for (const dependencyName of dependencyNames) {
      compute(dependencyName)
      if (finish.get(dependencyName) > taskStart) taskStart = finish.get(dependencyName)
      if (depth.get(dependencyName) + 1 > taskDepth) taskDepth = depth.get(dependencyName) + 1
    }
    start.set(name, taskStart)
    finish.set(name, taskStart + tasks.get(name))
    depth.set(name, taskDepth)
  }

  for (const name of tasks.keys()) compute(name)

  return { start, finish, depth }
}

/**
 * Groups task names by wave depth, ascending name order within each wave,
 * ascending depth order across waves.
 */
export function groupByWave(tasks, depth) {
  const waves = []
  for (const name of [...tasks.keys()].sort()) {
    const d = depth.get(name)
    if (!waves[d]) waves[d] = []
    waves[d].push(name)
  }
  return waves.map((wave) => wave ?? [])
}

/**
 * Priority for `pack`: the cost of the longest chain of costs starting at
 * a task and following the tasks that depend on it, down to a task nothing
 * depends on.
 */
function computePriorities(tasks, successors) {
  const priority = new Map()

  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    let longestSuccessorChain = 0
    for (const successorName of successors.get(name) ?? []) {
      const successorPriority = compute(successorName)
      if (successorPriority > longestSuccessorChain) longestSuccessorChain = successorPriority
    }
    const value = tasks.get(name) + longestSuccessorChain
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}

/**
 * Simulates the build on a fixed number of workers, greedily starting the
 * highest-priority ready task on the lowest-index free worker whenever
 * both are available at the current instant.
 */
export function pack(tasks, deps, workerCount) {
  const names = [...tasks.keys()]
  const successors = new Map()
  for (const name of names) successors.set(name, [])
  for (const [name, dependencyNames] of deps) {
    for (const dependencyName of dependencyNames) {
      successors.get(dependencyName).push(name)
    }
  }
  const priority = computePriorities(tasks, successors)

  const workers = Array.from({ length: workerCount }, () => ({ freeAt: 0, entries: [] }))
  const finishTime = new Map()
  const started = new Set()
  let time = 0

  function isReady(name) {
    const dependencyNames = deps.get(name)
    if (!dependencyNames) return true
    for (const dependencyName of dependencyNames) {
      const dependencyFinish = finishTime.get(dependencyName)
      if (dependencyFinish === undefined || dependencyFinish > time) return false
    }
    return true
  }

  function pickReadyTask() {
    let best = null
    for (const name of names) {
      if (started.has(name) || !isReady(name)) continue
      if (best === null) {
        best = name
        continue
      }
      const namePriority = priority.get(name)
      const bestPriority = priority.get(best)
      if (namePriority > bestPriority || (namePriority === bestPriority && name < best)) best = name
    }
    return best
  }

  function pickFreeWorker() {
    for (let i = 0; i < workers.length; i++) {
      if (workers[i].freeAt <= time) return i
    }
    return -1
  }

  while (started.size < names.length) {
    let assignedThisRound = true
    while (assignedThisRound) {
      assignedThisRound = false
      const workerIndex = pickFreeWorker()
      if (workerIndex === -1) break
      const taskName = pickReadyTask()
      if (taskName === null) break

      const cost = tasks.get(taskName)
      const start = time
      const finish = time + cost
      workers[workerIndex].entries.push({ name: taskName, start, finish })
      workers[workerIndex].freeAt = finish
      finishTime.set(taskName, finish)
      started.add(taskName)
      assignedThisRound = true
    }

    if (started.size >= names.length) break

    let nextFree = Infinity
    for (const worker of workers) {
      if (worker.freeAt > time && worker.freeAt < nextFree) nextFree = worker.freeAt
    }
    if (nextFree === Infinity) break
    time = nextFree
  }

  return workers
}
"}

