 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { parseGraph } from './parse.js'
import { checkForCycle, computeTimings, groupByWave, pack } from './schedule.js'
import { CliError, CycleError } from './errors.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const WORKERS_PATTERN = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_PATTERN.test(argv[1])) {
      throw new CliError('error: workers must be a positive integer')
    }
    return { mode: 'pack', workerCount: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE)
}

function runWaves(tasks, deps) {
  const { finish, depth } = computeTimings(tasks, deps)
  const waves = groupByWave(tasks, depth)
  const lines = waves.map((wave, index) => `wave ${index}: ${wave.join(' ')}`)
  let total = 0
  for (const value of finish.values()) if (value > total) total = value
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function runExplain(tasks, deps) {
  const { start, finish, depth } = computeTimings(tasks, deps)
  const lines = [...tasks.keys()]
    .sort()
    .map((name) => `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)
  let total = 0
  for (const value of finish.values()) if (value > total) total = value
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function runPack(tasks, deps, workerCount) {
  const workers = pack(tasks, deps, workerCount)
  const lines = workers.map((worker, index) => {
    const entries = worker.entries.map((entry) => ` ${entry.name}@${entry.start}-${entry.finish}`).join('')
    return `worker ${index}:${entries}`
  })
  let makespan = 0
  for (const worker of workers) {
    for (const entry of worker.entries) {
      if (entry.finish > makespan) makespan = entry.finish
    }
  }
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  const args = parseArgs(process.argv.slice(2))
  const input = readFileSync(0, 'utf8')
  const { tasks, deps } = parseGraph(input)
  checkForCycle(tasks, deps)

  if (args.mode === 'waves') return process.stdout.write(runWaves(tasks, deps))
  if (args.mode === 'explain') return process.stdout.write(runExplain(tasks, deps))
  return process.stdout.write(runPack(tasks, deps, args.workerCount))
}

try {
  main()
} catch (error) {
  if (error instanceof CycleError) {
    process.stderr.write(error.message + '\n')
    process.exit(3)
  }
  if (error instanceof CliError) {
    process.stderr.write(error.message + '\n')
    process.exit(2)
  }
  throw error
}
"}

